code.cpp:
class Solution {
public:
    int maximumInvitations(vector<int>& favorite) {
        int n = favorite.size();
        vector<int> indeg(n, 0);
        for (int i = 0; i < n; i++) indeg[favorite[i]]++;

        vector<int> dp(n, 0);

        queue<int> q;
        for (int i = 0; i < n; i++) {
            if (indeg[i] == 0) q.push(i);
        }

        while (!q.empty()) {
            int u = q.front(); q.pop();
            int v = favorite[u];
            dp[v] = max(dp[v], dp[u] + 1);
            if (--indeg[v] == 0) q.push(v);
        }

        int maxCycle = 0;
        int twoCycleSum = 0;
        vector<bool> visited(n, false);

        for (int i = 0; i < n; i++) {
            if (indeg[i] > 0 && !visited[i]) {
                int len = 0;
                int cur = i;
                while (!visited[cur]) {
                    visited[cur] = true;
                    cur = favorite[cur];
                    len++;
                }
                if (len == 2) {
                    int a = i;
                    int b = favorite[i];
                    twoCycleSum += 2 + dp[a] + dp[b];
                } else {
                    maxCycle = max(maxCycle, len);
                }
            }
        }

        return max(maxCycle, twoCycleSum);
    }
};
